import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        long total = 0;
        for (int i = 0; i < n; i++) {
            a[i] = nextLong();
            total += a[i];
        }
        Arrays.sort(a); // ascending: the largest remaining element is at the back
        // Take the largest remaining element until the taken sum beats the rest.
        long taken = 0;
        int count = 0;
        while (count < n) {
            taken += a[n - 1 - count++];
            if (taken > total - taken) break;
        }
        StringBuilder sb = new StringBuilder().append(count).append('\n');
        for (int i = n - count; i < n; i++) sb.append(a[i]).append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	a := make([]int64, n)
	var total int64
	for i := range a {
		a[i] = nextInt()
		total += a[i]
	}
	slices.Sort(a) // ascending: the largest remaining element is at the back
	// Take the largest remaining element until the taken sum beats the rest.
	var taken int64
	count := 0
	for count < n {
		taken += a[n-1-count]
		count++
		if taken > total-taken {
			break
		}
	}
	out := strconv.AppendInt(nil, int64(count), 10)
	out = append(out, '\n')
	for _, v := range a[n-count:] {
		out = strconv.AppendInt(out, v, 10)
		out = append(out, '\n')
	}
	os.Stdout.Write(out)
}
